using Microsoft.AspNetCore.Mvc.RazorPages;
using System.Text.Json;

namespace SkillBridge.Pages
{
    public class JobsModel : PageModel
    {
        public List<RecommendedJob> RecommendedJobs { get; set; } = new();

        public void OnGet()
        {
            // Get personalized jobs generated by ResumeAnalyzer
            var jobsJson = TempData.Peek("RecommendedJobs") as string;

            if (!string.IsNullOrEmpty(jobsJson))
            {
                try
                {
                    RecommendedJobs =
                        JsonSerializer.Deserialize<List<RecommendedJob>>(jobsJson)
                        ?? new List<RecommendedJob>();
                }
                catch
                {
                    RecommendedJobs = new List<RecommendedJob>();
                }
            }
        }
    }
}